#include "main.h"
#include "app.h"
#include <stdint.h>

// Handles generated by CubeMX in main.c
extern IWDG_HandleTypeDef hiwdg;
extern TIM_HandleTypeDef htim3;

// Tunable timings (in milliseconds unless noted)
#define QUALIFY_MS              5u    // inputs healthy this long before closing allowed
#define SWITCH_DEBOUNCE_MS      20u   // S501 must hold a level this long to register
#define HANDOVER_STABLE_MS      2u    // L-L must persist across 2 ticks (>= 1 ms real time)
#define PRECHARGE_TIMEOUT_MS    100u  // nominal ~20 ms for 2 mF; fault if exceeded
#define HANDOVER_OVERLAP_MS     5u    // CCEN and PREEN both on before PREEN drops
#define CONFIRM_US              50u   // OV/UV/PGOOD must stay bad this long to trip
#define HEARTBEAT_MS            100u  // LED toggle while running
#define HEARTBEAT_FAULT_STEP_MS 1000u // LED toggle when faulted: (fault bit index + 1) x this

// Glitch indication: two quick blinks then a pause, repeated three times.
// Steps alternate ON, OFF, ON, OFF, ... starting with ON.
#define GLITCH_REPEATS          3u
static const uint16_t glitch_step_ms[] = { 100u, 100u, 100u, 700u };
#define GLITCH_STEPS_PER_REPEAT (sizeof glitch_step_ms / sizeof glitch_step_ms[0])

// Fast pin access functions (for single-cycle register operations)
static inline bool pin_high(GPIO_TypeDef *port, uint16_t pin) { return (port->IDR & pin) != 0u; }
static inline void pin_set (GPIO_TypeDef *port, uint16_t pin) { port->BSRR = pin; }
static inline void pin_clr (GPIO_TypeDef *port, uint16_t pin) { port->BRR  = pin; }

/*
   Comparator polarity (AMC23C14 datasheet, window-comparator mode)

     OUT1 (adjustable REF): LOW when the input is ABOVE its threshold
     OUT2 (fixed 300 mV)  : LOW when the input is ABOVE its threshold
     Loss of VDD1         : BOTH outputs LOW

   U301 input bus : OUT1 = INCMP1 (OV 65.8 V), OUT2 = INCMP2 (UV 48.6 V)
   U302 output bus: OUT1 = OUTCMP1 (~55.6 V; 48.1 V until R314 is swapped),
                    OUT2 = OUTCMP2 (~45.2 V)

   Input bus healthy = INCMP1 high, INCMP2 low. A dead U301 supply reads
   as overvoltage, so the relay opens.

   Both comparators take VDD1 from the input bus, so U302 is powered
   before the relay acts and L-L genuinely means the output is above the
   OUTCMP1 threshold. If the output is already charged when S501 closes,
   the handover happens straight away with no inrush.
*/
#define INPUT_NOT_OV()      ( pin_high(INCMP1_GPIO_Port,  INCMP1_Pin))
#define INPUT_NOT_UV()      (!pin_high(INCMP2_GPIO_Port,  INCMP2_Pin))
#define OUTPUT_ABOVE_55V()  (!pin_high(OUTCMP1_GPIO_Port, OUTCMP1_Pin))
#define OUTPUT_ABOVE_45V()  (!pin_high(OUTCMP2_GPIO_Port, OUTCMP2_Pin))

// TPSI open-drain outputs: FLT1/ALM1 active-low, PGOOD high = supply good
#define CC_SUPPLY_OK()      ( pin_high(CCPGOOD_GPIO_Port,  CCPGOOD_Pin))
#define PRE_SUPPLY_OK()     ( pin_high(PREPGOOD_GPIO_Port, PREPGOOD_Pin))
#define CC_NO_TRIP()        ( pin_high(CCFLT_GPIO_Port,    CCFLT_Pin))
#define CC_NO_ALARM()       ( pin_high(CCALM_GPIO_Port,    CCALM_Pin))

// S501 switches PF0 to GND against the internal pull-up: LOW = ON
#define SWITCH_RAW_ON()     (!pin_high(SWITCH_GPIO_Port, SWITCH_Pin))

// State
static volatile relay_state_t   state =         STATE_INIT;
static volatile uint32_t        faults =        0u;
static volatile uint32_t        warnings =      0u;
static volatile uint32_t        first_fault =   0u;     // first fault bit latched; sets the blink rate

static uint32_t  t_state_entry;     // tick when current state was entered
static uint32_t  t_healthy_since;   // tick when inputs last became healthy
static bool      was_healthy;

static bool      sw_on;             // debounced S501 level
static bool      sw_raw_last;       // last raw S501 reading
static uint32_t  t_sw_change;       // tick of the last raw S501 change
static bool      sw_armed;          // S501 seen OFF while ready; next ON may close

static uint32_t  t_ll_since;        // tick of the last non-L-L reading

// Heartbeat / glitch pattern
static uint32_t  t_heartbeat;
static bool      glitch_active;     // glitch pattern currently playing
static uint32_t  glitch_step;       // index into the repeated step sequence
static uint32_t  glitch_count;      // glitches recorded (loop context only)
static uint32_t  glitch_shown;      // glitch_count when the last pattern started

/*
   Glitch rejection for the OV/UV and PGOOD lines.

   The precharge buck switches 60 V in tens of ns, and single-edge noise on
   these open-drain lines was latching faults mid-precharge. An edge on one
   of these lines now only marks the fault as pending. app_loop() trips if
   the line is still bad CONFIRM_US later, and otherwise drops the event,
   records it as a glitch warning (same bit position as the fault) and
   plays the glitch pattern on the heartbeat LED.

   Real OV/UV events last milliseconds, so the added latency (CONFIRM_US
   plus one loop pass) does not weaken protection. Overcurrent (CCFLT) is
   NOT filtered: the TPSI3103 has already acted on it in hardware.

   Timebase: TIM3 free-runs at 1 MHz (PSC 47, 48 MHz) for OUTCMP2 capture.
*/
static volatile uint32_t pending;           // fault bits awaiting confirmation
static volatile uint32_t recovered;         // pending bits whose line went good again
static volatile uint16_t t_pending_us[8];   // TIM3 count when each bit went pending
static volatile uint32_t t_pending_ms[8];   // HAL tick, guards against TIM3 wrap

static inline uint16_t us_now(void) { return (uint16_t)TIM3->CNT; }

static inline uint32_t bit_index(uint32_t bit)
{
    uint32_t i = 0u;
    while ((bit >>= 1) != 0u) { i++; }
    return i;
}

// Relay control

// Open both paths immediately. Safe to call from any context.
static inline void relay_open_all(void)
{
    pin_clr(CCEN_GPIO_Port, CCEN_Pin);
    pin_clr(PREEN_GPIO_Port, PREEN_Pin);
}

static inline bool is_energised(relay_state_t s)
{
    return (s == STATE_PRECHARGE) || (s == STATE_HANDOVER) || (s == STATE_ON);
}

// Record a fault, remembering which one latched first.
static inline void latch_fault(uint32_t fault_bit)
{
    if (faults == 0u) {
        first_fault = fault_bit;
    }
    faults |= fault_bit;
}

// Open first, then record. Safe from ISRs.
static inline void trip(uint32_t fault_bit)
{
    relay_open_all();
    latch_fault(fault_bit);
}

// Fault blink: bit 0 -> 1 s, bit 1 -> 2 s, ... bit 6 -> 7 s per toggle.
static uint32_t fault_blink_ms(uint32_t fault_bit)
{
    return (bit_index(fault_bit) + 1u) * HEARTBEAT_FAULT_STEP_MS;
}

/*
    Assert an enable pin and change state, but only if no fault is latched.
    ISRs are masked for a few cycles so an ISR cannot latch a fault between
    the check and the pin write.
*/
static bool energise(GPIO_TypeDef *port, uint16_t pin, relay_state_t next)
{
    bool ok;
    __disable_irq();
    ok = (faults == 0u);
    if (ok) {
        state = next;
        pin_set(port, pin);
    }
    __enable_irq();
    return ok;
}

static void enter_state(relay_state_t next)
{
    state = next;
    t_state_entry = HAL_GetTick();
}

// Input health
static bool inputs_healthy_now(void)
{
    return  INPUT_NOT_OV() && INPUT_NOT_UV() &&
            CC_SUPPLY_OK() && PRE_SUPPLY_OK() && CC_NO_TRIP();
}

// Debounced: healthy continuously for QUALIFY_MS. Call once per loop.
static bool inputs_qualified(uint32_t now)
{
    if (inputs_healthy_now()) {
        if (!was_healthy) {
            was_healthy = true;
            t_healthy_since = now;
        }
        return (now - t_healthy_since) >= QUALIFY_MS;
    }
    was_healthy = false;
    return false;
}

// S501: debounce the raw level. Call once per loop.
static void switch_poll(uint32_t now)
{
    bool raw = SWITCH_RAW_ON();
    if (raw != sw_raw_last) {
        sw_raw_last = raw;
        t_sw_change = now;
    } else if ((now - t_sw_change) >= SWITCH_DEBOUNCE_MS) {
        sw_on = raw;
    }
}

/*
   Arming: a close needs S501 seen OFF while ready (STATE_OFF), then ON.
   S501 ON in any other idle state (INIT after reset, unhealthy inputs)
   disarms it, so the relay never closes on its own when the inputs
   recover with the switch already ON. Call after switch_poll().
*/
static void switch_arm(relay_state_t s)
{
    if (s == STATE_OFF && !sw_on) {
        sw_armed = true;
    } else if (!is_energised(s) && s != STATE_OFF && sw_on) {
        sw_armed = false;
    }
}

// Called from the EXTI ISR for a debounced line.
static inline void mark_line(uint32_t bit, bool bad)
{
    uint32_t i = bit_index(bit);
    if (bad) {
        pending   |=  bit;
        recovered &= ~bit;
        t_pending_us[i] = us_now();
        t_pending_ms[i] = HAL_GetTick();
    } else if ((pending & bit) != 0u) {
        recovered |= bit;
    }
}

// Current level of a debounced line (true = still bad).
static bool line_bad(uint32_t bit)
{
    switch (bit) {
    case FAULT_INPUT_OV:   return !INPUT_NOT_OV();
    case FAULT_INPUT_UV:   return !INPUT_NOT_UV();
    case FAULT_CC_SUPPLY:  return !CC_SUPPLY_OK();
    case FAULT_PRE_SUPPLY: return !PRE_SUPPLY_OK();
    default:               return false;
    }
}

// Resolve pending events. Call once per loop pass.
static void confirm_pending(bool live)
{
    if (!live) {
        __disable_irq();
        pending   = 0u;
        recovered = 0u;
        __enable_irq();
        return;
    }

    for (uint32_t bit = FAULT_INPUT_OV; bit <= FAULT_PRE_SUPPLY; bit <<= 1) {
        __disable_irq();
        bool     is_pending = (pending & bit) != 0u;
        bool     went_good  = (recovered & bit) != 0u;
        uint32_t i          = bit_index(bit);
        uint16_t dt_us      = (uint16_t)(us_now() - t_pending_us[i]);
        uint32_t dt_ms      = HAL_GetTick() - t_pending_ms[i];
        __enable_irq();

        if (!is_pending) {
            continue;
        }
        if (went_good || !line_bad(bit)) {
            // Glitch: drop it, record it, and flag it on the LED.
            __disable_irq();
            pending   &= ~bit;
            recovered &= ~bit;
            warnings  |=  bit;
            __enable_irq();
            glitch_count++;
        } else if (dt_us >= CONFIRM_US || dt_ms >= 2u) {
            // Still bad after the confirm window: real fault.
            trip(bit);
            __disable_irq();
            pending &= ~bit;
            __enable_irq();
        }
    }
}

// Heartbeat LED
static inline void led_write(bool on)
{
    if (on) { pin_set(HEARTBEAT_GPIO_Port, HEARTBEAT_Pin); }
    else    { pin_clr(HEARTBEAT_GPIO_Port, HEARTBEAT_Pin); }
}

/*
   Priority: fault code > glitch pattern > running heartbeat.
   A glitch that arrives while the pattern is playing is not lost: the
   pattern plays again when the current one finishes.
*/
static void heartbeat_update(uint32_t now)
{
    if (state == STATE_FAULT) {
        glitch_active = false;
        if ((now - t_heartbeat) >= fault_blink_ms(first_fault)) {
            t_heartbeat = now;
            HAL_GPIO_TogglePin(HEARTBEAT_GPIO_Port, HEARTBEAT_Pin);
        }
        return;
    }

    if (!glitch_active && glitch_count != glitch_shown) {
        glitch_shown  = glitch_count;
        glitch_active = true;
        glitch_step   = 0u;
        t_heartbeat   = now;
        led_write(true);                        // step 0 is ON
    }

    if (glitch_active) {
        uint32_t idx = glitch_step % GLITCH_STEPS_PER_REPEAT;
        if ((now - t_heartbeat) >= glitch_step_ms[idx]) {
            t_heartbeat = now;
            glitch_step++;
            if (glitch_step >= GLITCH_REPEATS * GLITCH_STEPS_PER_REPEAT) {
                glitch_active = false;          // done: back to the normal heartbeat
                led_write(false);
            } else {
                led_write((glitch_step % 2u) == 0u);  // even steps ON, odd steps OFF
            }
        }
        return;
    }

    if ((now - t_heartbeat) >= HEARTBEAT_MS) {
        t_heartbeat = now;
        HAL_GPIO_TogglePin(HEARTBEAT_GPIO_Port, HEARTBEAT_Pin);
    }
}

// Public API
void app_init(void)
{
    // Stop the IWDG counting while halted at a breakpoint (debug only).
    __HAL_RCC_DBGMCU_CLK_ENABLE();
    __HAL_DBGMCU_FREEZE_IWDG();

    relay_open_all();
    pin_clr(SCOPE_GPIO_Port, SCOPE_Pin);
    led_write(false);

    uint32_t now   = HAL_GetTick();
    t_state_entry  = now;
    t_heartbeat    = now;
    state          = STATE_INIT;

    // Start from the current level, unarmed: a switch left ON after a reset
    // must be turned OFF then ON again to close the relay.
    sw_raw_last    = SWITCH_RAW_ON();
    sw_on          = sw_raw_last;
    t_sw_change    = now;
    sw_armed       = false;

    HAL_TIM_IC_Start_IT(&htim3, TIM_CHANNEL_4);     // OUTCMP2 edges, and the 1 MHz timebase
}

void app_loop(void)
{
    uint32_t now       = HAL_GetTick();
    bool     qualified = inputs_qualified(now);

    switch_poll(now);

    // ---- Confirm or reject pending OV/UV/PGOOD events ----
    confirm_pending(is_energised(state));

    // ---- Any fault latched by an ISR forces the fault state ----
    if (faults != 0u && state != STATE_FAULT) {
        relay_open_all();
        enter_state(STATE_FAULT);
        led_write(false);                       // start the fault blink from off
        t_heartbeat = now;
    }

    // ---- S501 OFF opens the relay from any energised state ----
    if (!sw_on && is_energised(state)) {
        relay_open_all();
        enter_state(STATE_INIT);                // re-qualify before next close
    }

    switch_arm(state);

    // ---- State machine ----
    uint32_t in_state = now - t_state_entry;

    switch (state) {
    case STATE_INIT:
        relay_open_all();
        if (qualified) {
            enter_state(STATE_OFF);
        }
        break;

    case STATE_OFF:
        relay_open_all();
        if (!qualified) {
            enter_state(STATE_INIT);
        } else if (sw_on && sw_armed) {
            sw_armed   = false;                 // one close per OFF -> ON
            t_ll_since = now;
            if (energise(PREEN_GPIO_Port, PREEN_Pin, STATE_PRECHARGE)) {
                enter_state(STATE_PRECHARGE);
            }
        }
        break;

    case STATE_PRECHARGE: {
        bool ll = OUTPUT_ABOVE_55V() && OUTPUT_ABOVE_45V();   // code L-L: above OUTCMP1 level
        if (!ll) {
            t_ll_since = now;
        } else if ((now - t_ll_since) >= HANDOVER_STABLE_MS) {
            if (energise(CCEN_GPIO_Port, CCEN_Pin, STATE_HANDOVER)) {
                enter_state(STATE_HANDOVER);
            }
        }
        if (state == STATE_PRECHARGE && in_state > PRECHARGE_TIMEOUT_MS) {
            // Also expected if the input bus is below the OUTCMP1 threshold, or
            // the load draws more than the precharge current limit at that level.
            trip(FAULT_PRECHARGE_TIMEOUT);
        }
        break;
    }

    case STATE_HANDOVER:
        if (in_state >= HANDOVER_OVERLAP_MS) {
            pin_clr(PREEN_GPIO_Port, PREEN_Pin);
            enter_state(STATE_ON);
        }
        break;

    case STATE_ON:
        // Protection is interrupt-driven; nothing to poll here.
        break;

    case STATE_FAULT:
        relay_open_all();
        break;
    }

    // ---- Watchdog: refreshed only from the loop, every pass ----
    HAL_IWDG_Refresh(&hiwdg);

    // ---- Heartbeat LED ----
    heartbeat_update(now);
}

relay_state_t app_get_state(void)    { return state; }
uint32_t      app_get_faults(void)   { return faults; }
uint32_t      app_get_warnings(void) { return warnings; }

/*
   Interrupt callbacks (override HAL weak definitions)
   Priority 0 (EXTI, TIM3) - keep them short, no HAL_Delay.
*/

void HAL_GPIO_EXTI_Callback(uint16_t GPIO_Pin)
{
    pin_set(SCOPE_GPIO_Port, SCOPE_Pin);            // latency marker

    relay_state_t s = state;
    bool live = is_energised(s);

    switch (GPIO_Pin) {
    case CCFLT_Pin:
        // Not debounced: the TPSI3103 has already acted in hardware.
        if (!CC_NO_TRIP()) {
            relay_open_all();                       // stop TPSI3103 auto-retry
            if (live) { latch_fault(FAULT_OVERCURRENT); }
        }
        break;

    // Debounced lines: mark pending (or recovered); app_loop() decides.
    case INCMP1_Pin:
        if (live) { mark_line(FAULT_INPUT_OV,   !INPUT_NOT_OV()); }
        break;

    case INCMP2_Pin:
        if (live) { mark_line(FAULT_INPUT_UV,   !INPUT_NOT_UV()); }
        break;

    case CCPGOOD_Pin:
        if (live) { mark_line(FAULT_CC_SUPPLY,  !CC_SUPPLY_OK()); }
        break;

    case PREPGOOD_Pin:
        if (live) { mark_line(FAULT_PRE_SUPPLY, !PRE_SUPPLY_OK()); }
        break;

    case CCALM_Pin:
        if (!CC_NO_ALARM()) { warnings |= WARN_OC_ALARM; }
        break;

    case OUTCMP1_Pin:
        // Handover level is polled in the loop; no action on edges.
        break;

    default:
        break;
    }

    pin_clr(SCOPE_GPIO_Port, SCOPE_Pin);
}

// OUTCMP2 (PB1) arrives via TIM3 CH4 input capture, both edges.
void HAL_TIM_IC_CaptureCallback(TIM_HandleTypeDef *htim)
{
    if (htim->Instance != TIM3 || htim->Channel != HAL_TIM_ACTIVE_CHANNEL_4) {
        return;
    }
    pin_set(SCOPE_GPIO_Port, SCOPE_Pin);

    relay_state_t s = state;
    // OUTCMP2 going high after handover means the output fell below ~45.2 V.
    // U302 is powered from the input bus, so a full collapse to 0 V still
    // reads H-H here. Caught on the edge rather than polled for the fastest trip.
    if ((s == STATE_HANDOVER || s == STATE_ON) && !OUTPUT_ABOVE_45V()) {
        trip(FAULT_OUTPUT_COLLAPSE);
    }

    pin_clr(SCOPE_GPIO_Port, SCOPE_Pin);
}
